INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(50420, 'deDE', 'Ein leicht geschütteltes Geschenk', '', '', '', '', '', '', '', '', 25549),
(49474, 'deDE', 'Der verfluchte Splitter', 'Bringt den verfluchten Splitter zu Arkanomant Vridiel in Dalaran auf den Verheerten Inseln.', '<Ein unnatürlich metallischer Splitter erregt mit seinem mehrfarbigen Schimmern Eure Aufmerksamkeit. Als Ihr ihn berührt, bläht sich ein Ende auf und schmilzt dann dahin. Tropfen fallen zischend zu Boden und ein ätzender Gestank erfüllt Eure Nase.$b$bIn Dalaran sollte es jemanden geben, der sich mit Metallen beschäftigt und mehr darüber sagen kann.>', '', '', '', '', '', '', 25549),
(49473, 'deDE', 'Eine titanische Leistung', 'Bringt $1oa erweckende Essenz zu Arkanomant Vridiel.', 'Die Reaktion läuft von Tag zu Tag immer schneller ab. Vielleicht werden wir den Kampf gegen die Legion gewinnen, nur um etwas zu verlieren, das uns lieb und teuer ist.\n\nSind das die Vorzeichen eines größeren Umbruchs, der uns bevorsteht? Welches Schicksal erwartet unsere Welt, $n?\n\nIch werde nach Antworten in meiner Schmiede suchen, wie ich es schon immer getan habe. Eure Antworten, vermute ich, erwarten Euch andernorts.', '', '', '', '', '', '', 25549),
(49472, 'deDE', 'Eine titanische Leistung', 'Bringt $1oa erweckende Essenz zu Arkanomant Vridiel.', 'Illidan hat das Schicksal womöglich herausgefordert, doch Argus so nah an Azeroth heranzubringen, hat die Reaktion beschleunigt, die mit dem Kollaps des Nachtbrunnens begann.\n\nIch fürchte, was die Legion auf Argus tut, scheint weiter die Mächte zu destabilisieren, derer wir uns so viele Jahre unwissentlich bedient haben.\n\nNatürlich muss das näher untersucht werden.', '', '', '', '', '', '', 25549),
(49445, 'deDE', 'Der Ursargerithandel', '', '', '', '', '', '', '', '', 25549),
(49293, 'deDE', 'Invasionsoffensive', 'Schließt 3 normale Invasionspunkte ab.', 'Wir dürfen der Legion keine einzige Welt überlassen. Führt unsere Invasionspunktoffensive fort und zermalmt die verdammte Legion.', '', '', '', '', '', '', 25549),
(49224, 'deDE', 'Der Netherlichttiegel', 'Erfüllt ein Relikt mit Netherlichtstärkung, indem Ihr den Netherlichttiegel verwendet.', 'Der Tiegel surrt voller Macht. Schon bald werden Eure Waffen strahlen wie die Sterne!\n\nFür eine Chance, die Legion hier zu vernichten, werden wir diese Stärke brauchen.\n\n$n, Ihr habt große Strapazen auf Euch genommen, um uns zu diesem Punkt zu führen. Die Ehre, die Macht des Tiegels erstmals zu verwenden, muss die Eure sein.', '', '', '', '', '', '', 25549),
(49198, 'deDE', 'Großer Invasionspunkt: Inquisitor Meto', '', '', '', '', '', '', '', '', 25549),
(49196, 'deDE', 'Großer Invasionspunkt: Grubenlord Vilemus', '', '', '', '', '', '', '', '', 25549),
(49143, 'deDE', 'Essenz der Lichtmutter', 'Sammelt $1oa Lichtüberreste.', 'Das ist der entscheidende Moment, $n. Unsere Kampagne darf nicht ins Stocken geraten.\n\nXe''ra ist zwar gefallen, aber ich spüre immer noch ihre Präsenz überall um uns herum. Das Licht, das einst ihr Herz erhellte, kann unserer Sache immer noch Kraft spenden.\n\nZweifellos hat Xe''ras Verlust Turalyon tief getroffen. Ich werde alles in meiner Macht Stehende tun, um seinem aufgewühlten Geist Trost zu spenden, während Ihr die verbleibenden Überreste der Naaru sucht.', '', '', '', '', '', '', 25549),
(49135, 'deDE', 'Das Herz von Argus', 'Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Mythisch''.', 'Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.', '', '', '', '', '', '', 25549),
(49134, 'deDE', 'Das Herz von Argus', 'Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Heroisch''.', 'Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.', '', '', '', '', '', '', 25549),
(49133, 'deDE', 'Das Herz von Argus', 'Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Normal''.', 'Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.', '', '', '', '', '', '', 25549),
(49099, 'deDE', 'Invasionspunkt: Bonich', '', '', '', '', '', '', '', '', 25549),
(49098, 'deDE', 'Invasionspunkt: Cen''gar', '', '', '', '', '', '', '', '', 25549),
(49097, 'deDE', 'Invasionspunkt: Sangua', '', '', '', '', '', '', '', '', 25549),
(49096, 'deDE', 'Invasionspunkt: Naigtal', '', '', '', '', '', '', '', '', 25549),
(49091, 'deDE', 'Invasionspunkt: Val', '', '', '', '', '', '', '', '', 25549),
(49077, 'deDE', 'Momente der Reue', 'Bringt Illidans Kristall zu den Personen und Orten, die ihm am meisten am Herzen liegen.', '<Der Kristall ruft Euch und vibriert vor Magie.\n\nAls Ihr ihn anfasst, hört Ihr das Echo einer vergangenen Nachricht, eine Aufgabe, die Illidan Euch anvertraut hat.>', '', '', '', '', '', '', 25549),
(49076, 'deDE', 'Dunkle Passage', 'Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Mythisch''.', 'Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.', '', '', '', '', '', '', 25549),
(49075, 'deDE', 'Dunkle Passage', 'Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Heroisch''.', 'Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.', '', '', '', '', '', '', 25549),
(49058, 'deDE', 'Einer-von-vielen', '', '', '', '', '', '', '', '', 25549),
(49056, 'deDE', 'Filzer', '', '', '', '', '', '', '', '', 25549),
(49055, 'deDE', 'Ohrensucher', '', '', '', '', '', '', '', '', 25549),
(49052, 'deDE', 'Mar''cuus', '', '', '', '', '', '', '', '', 25549),
(49048, 'deDE', 'Zinken', '', '', '', '', '', '', '', '', 25549),
(49047, 'deDE', 'Bukki', '', '', '', '', '', '', '', '', 25549),
(49046, 'deDE', 'Knirscher', '', '', '', '', '', '', '', '', 25549),
(49045, 'deDE', 'Todeskreischer', '', '', '', '', '', '', '', '', 25549),
(49043, 'deDE', 'Unheilsschimmer', '', '', '', '', '', '', '', '', 25549),
(49042, 'deDE', 'Übelklaue', '', '', '', '', '', '', '', '', 25549),
(49041, 'deDE', 'Verdammnishuf', '', '', '', '', '', '', '', '', 25549),
(49032, 'deDE', 'Dunkle Passage', 'Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad ''Normal''.', 'Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.', '', '', '', '', '', '', 25549),
(49015, 'deDE', 'Der Tod eines Titanen', 'Bezwingt die Seele von Argus in Antorus, dem Brennenden Thron.', 'Ich vermag es nicht, meine Trauer und meine Wut über Sargeras Taten zum Ausdruck zu bringen.$b$bMeine Heimatwelt Argus enthält die Seele eines Titanen. Die Verderbnis hat sie durchwachsen und eine Erlösung ist nun unmöglich. Ihre Macht treibt die endlose Armee der Legion an.$b$bWir müssen das Unmögliche vollbringen... in die Tiefen von Antorus dringen und die Verbindung zwischen Legion und Weltenseele trennen.$b$bBitte, $n. Setzt ihrem Leiden ein Ende. Wenn wir das düstere Herz von Argus zerschlagen, wird auch die Legion erliegen... und die Seele meiner Welt wird erlöst sein.', '', '', '', '', '', '', 25549),
(49014, 'deDE', 'Der Brennende Thron', 'Sprecht mit Großkonstrukteur Romuul über der Antorischen Ödnis und öffnet den Weg nach Antorus.', 'Die Zeit ist gekommen, $n, um unseren Angriff auf Antorus zu starten. Alles, wofür wir gekämpft haben, all die Opfer unserer Freunde und Familien, haben uns an diesen Punkt geführt.$b$bWir werden mit dem Urteil des Lichts auf die Mauern dieser verfluchten Zitadelle feuern und ihr Machtzentrum erstürmen. Wir werden der Legion ein Ende setzen.$b$bNach all Euren Taten ist es nur recht und billig, dass Euch diese Ehre zuteil wird. Sprecht mit Romuul und lasst uns die Mission zu Ende bringen.', '', '', '', '', '', '', 25549),
(49007, 'deDE', 'Kommandant an Deck!', 'Benutzt Vishax'' Portal.', '<Das Gerät springt mit einem Summen an, bereit, Euch zum Portal von Schwadronskommandant Vishax in der Antorischen Ödnis bringen.>', '', '', '', '', '', '', 25549),
(48983, 'deDE', 'Bergbauregeln', '', '', '', '', '', '', '', '', 25549),
(48982, 'deDE', 'Invasionspunkt: Aurinor', '', '', '', '', '', '', '', '', 25549),
(48977, 'deDE', 'Vorräte der Armee des Lichts', 'Sprecht mit Verteidigerin Jaelaana auf der Vindikaar, um Eure Belohnung zu erhalten.', 'Archenon poros, Champion.\n\nDie Armee des Lichts möchte Euch für Eure Hilfe im Kampf gegen die Legion auf Argus danken.\n\nBitte nehmt diese Vorräte zusammen mit unserer tiefen Dankbarkeit an. Mit Eurer unermüdlichen Unterstützung kommen wir unserem Ziel, die Legion ein für alle Mal zu vernichten, jeden Tag etwas näher.', '', '', '', '', '', '', 25549),
(48976, 'deDE', 'Vorräte des Argusvorstoßes', 'Sprecht mit Toraan dem Verehrten auf der Vindikaar.', '$ct, dank Eurer Bemühungen haben unsere Streitkräfte Vorräte entdeckt und sie davor bewahrt, dem Feind in die Hände zu fallen.\n\nDurch Eure fortwährende Unterstützung werden wir weitere Ressourcen anbieten können.', '', '', '', '', '', '', 25549),
(48974, 'deDE', 'Champion der Armee des Lichts', 'Sprecht mit Verteidigerin Jaelaana auf der Vindikaar.', 'Eure Verbündeten in der Armee des Lichts möchten Euch für Eure unermüdliche Unterstützung danken. Sie erwarten Euch auf der Vindikaar.', '', '', '', '', '', '', 25549),
(48973, 'deDE', 'Champion des Argusvorstoßes', 'Sprecht mit Toraan dem Verehrten auf der Vindikaar.', 'Eure Verbündeten im Argusvorstoß haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.', '', '', '', '', '', '', 25549),
(48959, 'deDE', 'Sitz des Triumvirats: Dunkle Spalte', '', '', '', '', '', '', '', '', 25549),
(48958, 'deDE', 'Ritualstörung', '', '', '', '', '', '', '', '', 25549),
(48954, 'deDE', 'Das Blut eines Titanen', 'Bringt das Blut von Argus, dem Zerrütter, zu Khadgar in Dalaran.', '<Vor Euren Augen verwandelt sich ein Tropfen Blut des gefallenen Titanen Argus zu einem makellosen Edelstein. Als Ihr ihn in Eurer Hand haltet, spürt Ihr die fast unvorstellbare Macht, die ihm entspringt... ebenso wie Echos von Qualen und Trauer.\n\nEs ist das letzte Überbleibsel einer Schlacht, die nicht zu gewinnen hätte sein sollen. Doch wie alle Siege hatte auch dieser einen enorm hohen Preis.\n\nIhr erkennt sofort, wem Ihr diesen Schatz überbringen solltet.>', '', '', '', '', '', '', 25549),
(48953, 'deDE', 'Sitz des Triumvirats: Rufer der Dunkelheit', '', '', '', '', '', '', '', '', 25549),
(48952, 'deDE', 'Knochen für alle', '', '', '', '', '', '', '', '', 25549),
(48937, 'deDE', 'Erschafft einen Portalgenerator des Netherwandlers.', '', '', '', '', '', '', '', '', 25549),
(48936, 'deDE', 'Slithon die Letzte', '', '', '', '', '', '', '', '', 25549),
(48931, 'deDE', 'Erwachte Behemoths', '', '', '', '', '', '', '', '', 25549),
(48929, 'deDE', 'Einschätzung des Gegners', 'Sprecht mit Turalyon.', 'Die Nachricht, dass unsere Vorräte nicht für den Angriff auf Antorus ausreichen, wird Euren Hochexarchen sicher mit Sorge erfüllen. Er ist nicht gewohnt, seine viel gepriesene Armee des Lichts als unzureichend zu betrachten.\n\nDoch sein Stolz interessiert mich nicht. Während er eine neue Strategie sucht, werde ich den Boden mit Dämonenblut tränken.\n\nGeht nun. Vor unserem endgültigen Sieg muss noch vieles getan werden.', '', '', '', '', '', '', 25549),
(48912, 'deDE', 'Versorgung des antorischen Feldzugs', 'Schließt 10 Invasionspunkte ab.', 'Zur Versorgung ihrer Kreuzzüge benötigt die Legion Rohmaterial von den eroberten Welten. Durchdringt die Legionsportale, vernichtet jeden Dämon, den Ihr findet, und haltet sie davon ab, ihre Kriegsmaschine mit Materialien zu versorgen.', '', '', '', '', '', '', 25549),
(48911, 'deDE', 'Leerenimpfung', 'Sammelt 100 Fragmente kondensierter Leere.', 'Alle, die vom Schatten berührt worden sind, hinterlassen bei ihrem Ableben Spuren der Leere. Wenn Ihr bei Euren Reisen in die Stadt genug davon einsammeln könnt und dann zu mir zurückkehrt, werde ich ein besonders reines Destillat daraus herstellen. \n\nWir können noch mehr von meinen Leuten retten.', '', '', '', '', '', '', 25549),
(48910, 'deDE', 'Vorräte für Krokuun', 'Sammelt $1oa Ordensressourcen.', 'Dieser unwirtliche Ort hat meinen Leuten nicht viel zu bieten. Wir verbringen fast die gesamte Zeit damit, Dinge zum Überleben zusammenzukratzen. Wenn ich mehr Vorräte hätte, könnte ich Euch einen weiteren Gratpirscher anbieten.\n\nWas meint Ihr, $gAußerweltler:Außerweltlerin;?', '', '', '', '', '', '', 25549),
(48875, 'deDE', 'Gut vermischt', '', '', '', '', '', '', '', '', 25549),
(48867, 'deDE', 'Oberster Alchemist Munculus', '', '', '', '', '', '', '', '', 25549),
(48866, 'deDE', 'Leerenwächterin Valsuran', '', '', '', '', '', '', '', '', 25549),
(48864, 'deDE', 'Der zerschlagene Schmied', 'Findet den Schmied Gaal.', '$C, ich glaube, dass es sich dabei um ein Stück des Schlüssels zur Waffenkammer des Triumvirats handeln könnte. Wir haben sie vor unserer Flucht von Argus hinter uns verschlossen. Atalaa, meine Stellvertreterin, führte eine Streitkraft an, um die Kammer zu sichern. Das ist nun schon so lange her...\n\nIch bin mir nicht mehr sicher, doch es gibt noch jemanden, der es genau wissen sollte. Der Schmied des Schlüssels hieß Gaal. Da in Krokuun noch Zerschlagene leben, könnte auch er noch am Leben sein.', '', '', '', '', '', '', 25549),
