UPDATE `quest_template_locale` SET `QuestDescription`='Ich habe ihren geheimen Flugplatz gefunden, $n: den Starkarmflugplatz. Schwer war es nicht, denn es wimmelt dort nur so von Truppen der Allianz.$b$b<Nazgrim spuckt auf den Boden.>$b$bSie denken, sie hätten uns ausgelöscht, aber wir sind die Horde! Wir kämpfen, bis zum Tod... und womöglich darüber hinaus. Lassen wir sie unseren Stahl kosten!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=31775 AND `locale`='deDE');
