UPDATE `quest_template_locale` SET `QuestDescription`='Genau unterhalb dieser Stadt befinden sich Feinde der Horde, $C.$B$BDie Angehörigen der Sengenden Klinge planen, Orgrimmar für sich einzunehmen, und sie haben bereits den Flammenschlund erobert! Wir müssen uns gegen ihre Truppen anstürmen und zurückerobern, was uns gehört!$B$BGeht und sprecht mit Kommandant Bagran im Flammenschlund. Er hat weitere Befehle für Euch.', `VerifiedBuild`=25549 WHERE (`ID`=31034 AND `locale`='deDE');
