UPDATE `quest_template_locale` SET `LogTitle`='Fische für Squrky', `LogDescription`='Angelt 3 blinde Elritzen aus dem Teich im Düsteren Viertel und verfüttert sie an Squrky.', `QuestDescription`='Hab ich Euch schon meinen Begleiter Squrky vorgestellt? Ich bringe ihm bei, wie man angelt, so richtig mit allen Schikanen! Bisher habe ich ihn mit Elritzen gefüttert, die ich aus dem Teich in diesem Viertel gefischt habe.$B$BVielleicht wollt Ihr es ja mal versuchen? Werft einfach Euren Köder in dem Teich da drüben aus und füttert Squrky mit den Elritzen, die Ihr rauszieht. Er wird Euch für immer lieben!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=29344 AND `locale`='deDE');
