UPDATE `quest_template_locale` SET `QuestDescription`='Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Generalleutnant Orion an den Stufen des Schicksals zu melden.$B$BDort werden Eure Fähigkeiten benötigt, um die Anwesenheit der Brennenden Legion auf den zerschmetterten Resten der Scherbenwelt zu bekämpfen.$B$BBegebt Euch zu Orgrimmars Kluft der Schatten und verwendet das Portal in der Nähe des Giftzutatenhändlers, um zur Höllenfeuerhalbinsel zu gelangen.$B$BFolgt dem Ruf des Schicksals!', `VerifiedBuild`=25549 WHERE (`ID`=28705 AND `locale`='deDE');
