UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Handelsbaron Silberschnapp in Kraulsumpf zu melden.$B$BDie Kräfte der Allianz brauchen dringend die vom Baron beschaffte Munition! Tut alles Nötige, um den Baron zu überzeugen, unsere Kräfte auch weiterhin zu vernünftigen Preisen zu versorgen.$B$BUm zu den Sümpfen zu gelangen, folgt Ihr der Straße von den südöstlichen Brennenden Steppen durch das Rotkammgebirge.$B$BRuhm und Ehre der Allianz!', `VerifiedBuild`=25549 WHERE (`ID`=28675 AND `locale`='deDE');
