UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Jack Felsbein am Thoriumvorstoß einzufinden.$B$BDer SI:7 meldet, dass die Dunkeleisenzwerge der Sengenden Schlucht anscheinend einen Angriff vorbereiten. Es ist Eure Pflicht, so viel wie möglich über ihre Machenschaften herauszufinden und sie zu durchkreuzen. $B$BIhr erreicht die Sengende Schlucht, indem Ihr im Ödland der Straße nach Westen folgt.$B$BFür den Ruhm und die Ehre der Allianz!', `VerifiedBuild`=25549 WHERE (`ID`=28582 AND `locale`='deDE');
