UPDATE `quest_template_locale` SET `QuestDescription`='Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...$b$bHm, schwer zu lesen, sieht aber aus wie der Name Mosarn. Nie von ihm gehört. Vielleicht kennt Krog ihn. Krog kennt viele Leute.', `VerifiedBuild`=25549 WHERE (`ID`=27257 AND `locale`='deDE');
