UPDATE `quest_template_locale` SET `QuestDescription`='Die Decks der Springflut sollten leuchten wie ein Sternrubin, $gDeckhelfer:Deckhelferin; $n. Ich führe ''n ordentliches Schiff, dafür sorgen Deckhelfer wie Ihr!$b$bNa, worauf wartet Ihr denn noch, Ihr miesmuscheldämliche Schiffsratte? Ans Deck mit Euch! Nehmt den Mopp in die Hand!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26633 AND `locale`='deDE');
