UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Greifenmeister Krallenaxt im Greifenhorst am Nistgipfel zu melden.$B$BUnsere neuen Brüder in der Allianz brauchen unsere Hilfe dabei, die aggressive Hordenoffensive in ihrer geliebten Heimat abzuwehren. Reist vom Arathihochland nach Norden durch den zwergischen Bergpass und folgt der Straße nach Nordwesten Richtung Nistgipfel.$B$BFür den Ruhm und die Ehre der Allianz!', `VerifiedBuild`=25549 WHERE (`ID`=26542 AND `locale`='deDE');
