UPDATE `quest_template_locale` SET `QuestDescription`='<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>$B$BDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!$B$BWir werden diesen feigen Grimmtotems nie gestatten, den Freiwindposten zu behalten! Bitte $C, rettet ihn, bevor es zu spät ist.', `PortraitGiverText`='Befreit ihn, bevor es zu spät ist.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=25872 AND `locale`='deDE');
