UPDATE `quest_template_locale` SET `LogTitle`='Nachricht für Saurfang', `LogDescription`='Bringt das Emblem des SI:7 zu Hochfürst Saurfang in der Feste Grommash in Orgrimmar.', `QuestDescription`='<Die Loyalistin der Dunkelspeere öffnet das Paket und liest den darin enthaltenen Brief. Als sie am Ende der Notiz ankommt, entblößt ein Lächeln ihre Fangzähne.>$B$BIhr bringt das besser direkt zu Saurfang in Orgrimmar. Lasst ihn auf jed''n Fall wiss''n, dass das Paket von Thrall stammt.$B$BNehmt meinen Raptor. Schnell, wir hab''n keine Zeit zu verlier''n!', `VerifiedBuild`=25549 WHERE (`ID`=25267 AND `locale`='deDE');
