UPDATE `quest_template_locale` SET `QuestDescription`='Es ist Zeit für Euch, uns zu verlassen, $n. Geht mit den anderen Zivilisten ins Militärviertel.$B$BMeldet Euch bei Gwen Armstead, wenn Ihr die Brücke im Südosten überquert... seht nach, ob es allen gut geht.$B$BIch werde mit den Wachen hierbleiben und den Rückzug der Zivilisten decken.$B$BGeht nun. Das ist ein Befehl!', `VerifiedBuild`=25549 WHERE (`ID`=14099 AND `locale`='deDE');
