UPDATE `quest_template_locale` SET `QuestDescription`='Da nun das inaktive Exemplar des Seuchenpräparats fertiggestellt ist und wir das Aktivierungsagens in Händen halten, fehlt uns nur noch eine passende Hülle für die Komponenten.$B$BSüdwestlich von hier an der zentralen Küste der Drachenöde liegt der Smaragddrachenschrein. Im Inneren des Schreins findet Ihr die hart gewordenen Überreste der Träne eines grünen Drachen. Ich kenn'' zwar nicht die ganze Geschichte, aber anscheinend weinen sie sehr viel, bevor sie sterben – stellt Euch vor.$B$BGeht zum Smaragddrachenschrein und sammelt Tränen.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12200 AND `locale`='deDE');
