UPDATE `quest_template_locale` SET `QuestDescription`='<V''erus Stimme erfüllt Euren Geist mit kristallener Melodie und Klarheit.>$B$BEs streunt ein Oger im Unteren Viertel umher, der alle Passanten um Hilfe anfleht. Doch keiner will seiner Not Gehör schenken. Könntet Ihr ihm vielleicht helfen?$B$BSein Name ist Grok. Er sitzt in der Nähe der Händler im Südosten.$B$BSeid bedankt, $n.', `VerifiedBuild`=25549 WHERE (`ID`=10984 AND `locale`='deDE');
