UPDATE `quest_template_locale` SET `LogTitle`='Esencias arcanas', `LogDescription`='Recupera $1oa esencias arcanas.', `QuestDescription`='Kaelynara no se detendrá hasta absorber hasta la última gota de energía arcana del cristal... y destruirá la mina al mismo tiempo. El escudo arcano que la protege no se puede penetrar de forma convencional, pero tengo un plan.$b$bSi tuviera un cristal de enfoque suficientemente potente como para perforar momentáneamente su escudo, nos podríamos encargar de Kaelynara.$b$bPor suerte, estamos en el lugar perfecto para construir uno. Empieza por traerme esencia arcana de las criaturas que están arrasando la mina.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=34401 AND `locale`='esES');
