UPDATE `quest_template_locale` SET `QuestDescription`='A lo mejor te apetece ayudarnos a investigar la corrupción que asola Cañada Umbría.$b$bDentaria Claro de Plata, sacerdotisa de la Luna, se ha ofrecido a ayudarnos. La encontrarás entre dos estanques justo al norte de nuestro gran árbol. Rodea el árbol para llegar hasta ella y ofrécele toda la ayuda que puedas, joven $c.', `VerifiedBuild`=25549 WHERE (`ID`=28723 AND `locale`='esES');
