UPDATE `quest_template_locale` SET `LogTitle`='La Piedra de la Muerte', `LogDescription`='Hazte con la Piedra de la Muerte.', `QuestDescription`='En el núcleo de Animus hay un artefacto conocido como la Piedra de la Muerte. Una de sus propiedades es la capacidad de absorber una gran cantidad de energía.$b$bEsa es la forma en la que los cultores planean desencadenar la explosión: sobrecargar la piedra y amplificar su energía a través del elemental.$b$bTráeme la Piedra de la Muerte. Para protegerla, claro está.', `PortraitGiverText`='¡Tiene la Piedra de la Muerte!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=28159 AND `locale`='esES');
