UPDATE `quest_template_locale` SET `QuestDescription`='El Sello del Rey del Sol es un mecanismo de defensa para Ramkahen.$B$BCuando la barrera que rodeaba Uldum cayó, comenzamos a avistar escoltas Vagayermos de Tanaris que se filtraban por nuestras fronteras.$B$BAtacaron este lugar sagrado de camino al oeste y lo robaron en busca de las reliquias que en otro tiempo les proporcionaron poder.$B$BRecupera las reliquias para nosotros. Sin ellas no podremos defendernos contra los ataques del desierto.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=28141 AND `locale`='esES');
