UPDATE `quest_template_locale` SET `LogDescription`='Habla con el nomarca Teneth en las Tierras de Tahret, con el sacerdote del Sol Asaris en el Sello del Rey del Sol y con Asaq en Mar''at.', `QuestDescription`='Ahora que has recibido una recompensa adecuada, espero poder hablar contigo sinceramente.$B$BHas hecho un gran favor a mi reino, pero también has desequilibrado un frágil proceso de paz.$B$BYo trataba de conseguir la liberación de mi hermano por medios estrictamente diplomáticos para evitar el derramamiento de sangre.$B$BAhora no cabe duda de que el enemigo buscará venganza.$B$BHabla con el nomarca Teneth en las Tierras de Tahret, al este de aquí; con el sacerdote del Sol Asaris en el Sello del Rey del Sol, al norte de aquí; y con Asaq en Mar''at, al oeste de aquí. Averigua dónde golpeará el enemigo.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=28134 AND `locale`='esES');
