UPDATE `quest_template_locale` SET `QuestDescription`='No dejo de escuchar los susurros de los elementos, $n...$b$b¡El Trono de las Mareas está bajo asedio!$b$bNo puedo quedarme aquí parado mientras los nagas amenazan el reino de Neptulon. Debemos encontrar un modo de unirnos a él.$b$bNazgrim me acompañará a las profundidades, donde podré comunicarme con Neptulon.$b$bA ti debo pedirte que sigas un camino más violento. Distrae a las fuerzas enemigas hasta que pueda llegar a la entrada del Torno de las Mareas.$b$bQue los espíritus nos guíen, $n.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26194 AND `locale`='esES');
