UPDATE `quest_template_locale` SET `LogDescription`='Usa el néctar sacro en el círculo de entierro de Aviana.', `QuestDescription`='A pesar de que la guardiana de todas las criaturas aladas ya no está con nosotros en forma corpórea, a veces escucho su voz en el susurro de las hojas al mecerse.$b$b$n, la labor que te solicitamos es muy dura, te enviamos a preservar esta montaña. Antes de irte, tómate un momento para reflexionar.$b$bLleva esta ofrenda de néctar al círculo de entierro de Aviana, un círculo de rocas que se encuentra justo a la salida de la puerta principal de este santuario. Tal vez si pasas un rato a solas con el recuerdo de Aviana, te ayude a concentrarte.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=25663 AND `locale`='esES');
