UPDATE `quest_template_locale` SET `LogDescription`='Bebe la poción de sigilo de Krennan en el Tramo de la Tempestad y asesina al Barón Ashbury y a lord Walden.', `QuestDescription`='¡El rey Cringrís es prisionero de lord Godfrey en el Tramo de la Tempestad!$B$BLogró convencer a dos señores del este para que colaborasen con su plan. Ese loco parece creer que puede firmar un acuerdo con los Renegados si les entrega a Cringrís.$B$BEscucha con atención, $n. Debemos resolver esto derramando la menor cantidad de sangre posible.$B$BEsta poción te permitirá infiltrarte sin que te detecten. ¡Necesitamos que asesines a los señores traidores antes de que la situación se nos escape de las manos!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24592 AND `locale`='esES');
