UPDATE `quest_template_locale` SET `LogDescription`='Recoge 100 calaveras blanquecinas en la Fortaleza del Hacha de Trueno, colócalas en el Círculo de Invocación del clan Filo Ardiente y después mata a Nazargen.', `QuestDescription`='Así que es cierto...$b$bEl pergamino que descubriste en la Fortaleza del Hacha de Trueno describe los detalles de un poderoso ritual de invocación. El más poderoso que sepamos que posee el clan Filo Ardiente.$b$b¡Debemos impedir que se celebre este rito a toda costa!$b$bQuizás, si invocáramos a este demonio antes de tiempo, evitaríamos la crisis.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=14364 AND `locale`='esES');
