UPDATE `quest_template_locale` SET `LogDescription`='Draaka quiere que lleves su carta de explicación al alto señor supremo Colmillosauro, en Orgrimmar.', `QuestDescription`='Esto podría significar mi final... Tal vez debería haber planificado mejor mis acciones...$b$bLo bueno es que repelimos un ataque que habría supuesto el final del Puesto del Hachazo. Esperemos que Colmillosauro también lo vea así.$b$bSeguro que me hacen ir a Orgrimmar a explicar mis actos.$b$bPor favor, $n, adelántate y entrégale esta carta.$b$bY haz lo posible para ablandarlo.', `PortraitGiverText`='Se espera que muestre algo de clemencia...', `VerifiedBuild`=25549 WHERE (`ID`=13841 AND `locale`='esES');
