UPDATE `quest_template_locale` SET `LogDescription`='Trae 5 colmillos de cobra intactos al Oráculo Soo-liloquio cerca de Los Huesos de Nozronn.', `QuestDescription`='No te conocemos, $gforastero:forastera;, pero sabemos que quieres algo.$b$bHablaremos con los Huesos de Nozronn por ti, pero tienes que traernos ofrendas. Necesitamos potentes colmillos de cobra emperador para completar el collar del Oráculo.$b$bVe a Manglar Silvestre, al noreste de esta barraca, busca cobras y tráenos los mejores colmillos. Luego, haremos que los huesos te hablen.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12543 AND `locale`='esES');
