UPDATE `quest_template_locale` SET `LogDescription`='La comandante Lynore Golpevento, en la Fortaleza de Hibergarde del Cementerio de Dragones, quiere que mates a 20 miembros de El Embate Escarlata del campamento del Embate.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12476 AND `locale`='esES');
