UPDATE `quest_template_locale` SET `LogTitle`='Atrapar la luz fantástica', `QuestDescription`='Los etéreos de Razaani han estado jugando con una tecnología muy interesante en la Zona de Aterrizaje Razaan, hacia el norte.$B$BSeguro que no les importa que utilices este dispositivo trampa para coger un par de muestras de sus pequeños orbes flotantes de luz rosa. De todas formas, probablemente solo sirven para decorar.$B$BLa trampa tiene una propiedad especial que, al abrirse, debería atraer una de las bolas flotantes. Aunque, probablemente, también alerte a los Razaani de tu presencia.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10674 AND `locale`='esES');
