UPDATE `quest_template_locale` SET `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10436 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Audi la Aguja, de Flecha de la Tormenta, quiere que le lleves diez segmentos de generador de domo.', `QuestDescription`='<Audi mira alrededor y baja la voz.>$B$BEstoy segura de que Shauly te habló un poco de nuestro trabajo aquí. Cuando Jaxon y yo estamos en el campo "cazando", reunimos piezas de los generadores de los ecodomos de los etéreos y las escondemos en los nidos de nuestra presa, los raptores del Ecodomo Campolejano.$B$BEs un lugar remoto al noreste de Flecha de la Tormenta, cerca de la Piedra Abisal. No preveo que te vayas a topar con muchos etéreos allí, ¿pero estarías $gdispuesto:dispuesta; a ayudarnos a reunir las piezas del generador de domos?', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10435 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Habla con Audi la Aguja en Flecha de la Tormenta, en Tormenta Abisal.', `QuestDescription`='Excelente trabajo.$B$B<Shauly te guiña un ojo.>$B$BCreo que se lo están tragando. Bueno, cuando te envíe a hablar con mis socios a Flecha de la Tormenta, no habrá ninguna sospecha en absoluto.$B$BBusca a Acción Jaxon y Audi la Aguja una vez allí. Te dirán todo lo que necesitas saber. Diles que te envía Shauly.', `VerifiedBuild`=25549 WHERE (`ID`=10434 AND `locale`='esES');
