UPDATE `quest_template_locale` SET `VerifiedBuild`=25549 WHERE (`ID`=10428 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Marca 12 talbuks para Aurine Lunardiente en Flecha de la Tormenta. Puedes marcar soberanos talbulks o ciervas talbuks utilizando el marcador talbuk.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10427 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Utiliza el modulador de campo de energía en los azotadores Farahlon. Observa los resultados y ve a ver a Aurine Lunardiente en Flecha de la Tormenta cuando hayas realizado 10 pruebas.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10426 AND `locale`='esES');
UPDATE `quest_template_locale` SET `PortraitGiverText`='', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10425 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogDescription`='Utiliza el aparato de diagnóstico cuando estés cerca del generador del Ecodomo Sutheron y lleva los resultados del diagnóstico a Ghabar en Flecha de la Tormenta.', `QuestDescription`='Si los resultados de Mehrdad son correctos, y no tengo ninguna razón para creer que no lo sean, entonces todos los domos podrían estar en peligro.$B$BCreo que Mehrdad se equivocó al identificar la causa de los fallos. De vez en cuando, las criaturas dañan los generadores, pero nunca con esta gravedad.$B$BPara quedarnos tranquilos, me gustaría que sacases los diagnósticos del generador principal del domo de Flecha de la Tormenta, situado en el Ecodomo Sutheron, en el punto más al este del domo.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10424 AND `locale`='esES');
UPDATE `quest_template_locale` SET `LogTitle`='Hacia Flecha de la Tormenta', `LogDescription`='Habla con Ghabar en Flecha de la Tormenta, en Tormenta Abisal.', `QuestDescription`='El maestro ingeniero Ghabar querrá saber los resultados del diagnóstico. Siempre nos están diciendo que vigilemos bien el funcionamiento de los generadores de los domos. Cuando aumente la inestabilidad de los campos, sus efectos serán cada vez más difíciles de controlar. Podría resultar un desastre para nuestra expedición y para cualquier otra cosa alojada en los domos.$B$BEncontrarás a Ghabar en Flecha de la Tormenta. Sigue el camino hacia el norte de este Ecodomo y cruza el puente que te llevará hasta el elevador de la base de La Flecha.', `VerifiedBuild`=25549 WHERE (`ID`=10423 AND `locale`='esES');
