UPDATE `quest_template_locale` SET `LogDescription`='Apportez le Cœur de la forêt à Hamuul Totem-Runique au Bosquet d’Aessina, sur le Mont Hyjal.', `QuestDescription`='<Nordu écarte les branches enflammées qui lui servent de doigts. Sa main renferme une graine brillante et intacte.>$b$bVoici le Cœur de la forêt. La graine de la vie.$b$bApportez-la à votre archidruide, au bosquet d’Aessina. Hamuul Totem-Runique saura comment invoquer son pouvoir. Je vous promets que l’esprit de la nature va faire entendre sa voix. Une vie nouvelle renaîtra sur les cendres des vies antérieures.$b$bMerci, $r. Mon heure est venue.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=25372 AND `locale`='frFR');
