UPDATE `quest_template_locale` SET `QuestDescription`='Une autre des étranges constructions de Mimiron, le Déconstructeur XT-002, pense qu''il est le fils du gardien. Mais ne vous laissez pas berner par sa fausse innocence. C''est une machine mortelle !$B$BVous trouverez le Déconstructeur dans la Ferraillerie d''Ulduar. Le Conseil des Six a décrété que le Déconstructeur XT-002 doit mourir !', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24588 AND `locale`='frFR');
