UPDATE `quest_template_locale` SET `QuestDescription`='Noth le Porte-Peste, un traître et un pleutre ! Il a gonflé le Fléau avec quasiment autant d''âmes que le roi-liche lui-même.$B$BHâtez-vous vers Naxxramas. Vous le trouverez dans le quartier de la Peste, caché derrière ses serviteurs morts-vivants.$B$BDétruisez-le ! Le Conseil des Six a décrété que Noth doit mourir !', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24581 AND `locale`='frFR');
