UPDATE `quest_template_locale` SET `LogTitle`='La purification de Crin-Sauvage', `LogDescription`='Utiliser le Totem de purification de Crin-Sauvage au puits Crin-Sauvage.', `QuestDescription`='Votre purification des puits Sabot-d’Hiver et Corne-tonnerre est un objet de discussion et de fierté parmi les esprits, jeune $n. Le totem de Crin-Sauvage est construit et le devoir vous appelle, encore une fois.$B$BLe puits Crin-sauvage se trouve au nord des Pitons-du-Tonnerre. Pratiquez-y le rituel ! Débarrassez le pays du poison des Totems-Sinistres. Que l''eau claire coule de nouveau !', `AreaDescription`='Purifier le puits Crin-Sauvage', `QuestCompletionLog`='Retournez voir Una Crin-Sauvage au Camp Frôle-soleil.', `VerifiedBuild`=25549 WHERE (`ID`=24524 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `LogTitle`='Le totem des Crin-Sauvage', `QuestDescription`='Il ne reste plus qu’un puits à purifier, celui qui porte le nom du clan Crin-Sauvage. Pour qu’il retrouve sa pureté, la terre doit offrir les dents d’un prédateur féroce, le loup alpha des prairies. Trouvez les alphas, au nord, et revenez me voir lorsque votre chasse sera terminée.$B$BLes alphas rôdent souvent autour de la base de notre grande cité des Pitons-du-Tonnerre.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=24523 AND `locale`='frFR');
