UPDATE `quest_template_locale` SET `QuestDescription`='Parfait !$b$bLa Horde va montrer aux elfes de quoi elle est capable quand on la met au pied du mur.$b$bÉcoutez, $n. Vous ne devez rien dire à personne !$b$bSaurcroc appréciera sûrement notre initiative quand il verra le résultat final, mais s’il découvre le pot aux roses trop tôt, nos corps iront se balancer au bout d’une corde !$b$b<Draaka vous tend une note écrite à la hâte.>$b$bApportez ça à Durak. Vous le trouverez dans les mines derrière moi, juste au nord. Il vous donnera de nouvelles instructions.', `VerifiedBuild`=25549 WHERE (`ID`=13751 AND `locale`='frFR');
