UPDATE `quest_template_locale` SET `LogDescription`='Amadouez les esprits de Thundris Tissevent, Elissa Soufflétoile, Taldan et Caylais Plumelune.', `QuestDescription`='Vos amis du camp de réfugiés n’ont aucune idée du danger imminent que les sectateurs du Marteau du crépuscule ont d’ores et déjà introduit dans ce monde.$B$BPour que vous puissiez l’affronter, il nous faudra l’aide des morts d’Auberdine.$B$BFouillez les ruines de la ville à la recherche des cadavres de Thundris Tissevent, Elissa Soufflétoile, Taldan et Caylais Plumelune. Amadouez leurs esprits, faites-les sortir de leurs corps, et revenez me voir en leur compagnie.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13547 AND `locale`='frFR');
