UPDATE `quest_template_locale` SET `LogDescription`='Tuez la Dompteuse de nuages Crin-Sauvage, le Maître du vent Tzu-Tzu et le Seigneur du ciel Braax.', `QuestDescription`='J’ai survolé les ruines d’Auberdine au cours d’une mission de reconnaissance. Trois sectateurs du Marteau du crépuscule sont responsables des élémentaires qui ont envahi notre ville détruite.$B$BAllez à l’ouest jusqu’aux ruines. Cherchez et abattez la dompteuse de nuages Crin-Sauvage, le maître du vent Tzu-Tzu et le seigneur du ciel Braax.$B$BLorsque ce sera fait, la sentinelle Selarin et ses forces auront une chance de reprendre leur foyer.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13543 AND `locale`='frFR');
