UPDATE `quest_template_locale` SET `QuestDescription`='Vous devez vous rendre à Ymirheim, la grande cité de givre des Vrykuls au centre de la Couronne de glace.$B$BNotre ami Exploz Tonnebombe est en bas, à l''ouest de la ville. Il représente l''Offensive chanteguerre dans un tournoi contre l''Alliance. Ce sera son sautomate contre celui de l''Alliance, dans le plus grand combat de la montagne !$B$BNe nous abandonnez pas, $n. La fierté de l''ingénierie gobeline est en jeu ! En plus, tous les gars du fort comptent sur vous.$B$BSans compter le fait que nous avons parié que vous sauriez massacrer ces trouillards de l''Alliance !', `VerifiedBuild`=25549 WHERE (`ID`=13293 AND `locale`='frFR');
