UPDATE `quest_template_locale` SET `LogDescription`='Le Lieutenant Murp, à la Forteresse de Joug-d’Hiver, vous a demandé de détruire 3 Engins de siège de l’Alliance.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13185 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `LogTitle`='Victoire à Joug-d’Hiver', `LogDescription`='Gagnez une bataille sur le champ de bataille de Joug-d’Hiver, et retournez voir l’Officier tactique Kilrath, à Joug-d’Hiver.', `QuestDescription`='Dardosh se satisfait peut-être de massacrer nos ennemis, mais le plus important est de contrôler la forteresse de Joug-d’Hiver. Faites ce qu’il faut pour que Joug-d’Hiver nous appartienne.$B$BCependant, ne croyez pas que vous pouvez vous contenter de rester $gplanté:plantée; là pendant que vos alliés feront le sale boulot à votre place. Si vous n’êtes pas $gmonté:montée; en grade à la fin de la bataille, ce n’est pas la peine de revenir me voir.', `AreaDescription`='Victoire au lac Joug-d’Hiver', `QuestCompletionLog`='Retournez voir l’Officier tactique Kilrath au Joug-d’Hiver.', `VerifiedBuild`=25549 WHERE (`ID`=13183 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13182 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `LogTitle`='Victoire à Joug-d’Hiver', `LogDescription`='Gagnez une bataille sur le champ de bataille de Joug-d’Hiver, et retournez voir l’Officier tactique Ahbramis, à Joug-d’Hiver.', `QuestDescription`='Le commandant Zanneth se satisfait peut-être d’avoir une pile de cadavres de la Horde à ses pieds, mais la possession de la forteresse de Joug-d’Hiver est de la plus haute importance pour l’expédition de la Bravoure. Faites ce qu’il faut pour que Joug-d’Hiver reste sous notre contrôle.$B$BCependant, ne croyez pas que vous pouvez vous contenter de rester $gplanté:plantée; là pendant que vos alliés feront le sale boulot à votre place. Si vous n’êtes pas $gmonté:montée; en grade à la fin de la bataille, ce n’est pas la peine de revenir me voir.', `AreaDescription`='Victoire au lac Joug-d’Hiver', `QuestCompletionLog`='Retournez voir l’Officier tactique Ahbramis au Joug-d’Hiver.', `VerifiedBuild`=25549 WHERE (`ID`=13181 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `LogDescription`='Le Commandant Dardosh, à Joug-d’Hiver, vous a demandé de tuer 10 membres de l’Alliance.', `QuestDescription`='Bienvenue à Joug-d’Hiver, $n. Le chef de guerre Garrosh ne demande qu’une chose : tuez-les tous !$B$BRevenez me voir quand dix des plus puissants membres de l’Alliance seront morts.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13180 AND `locale`='frFR');
