UPDATE `quest_template_locale` SET `QuestDescription`='Il est temps d’affronter Eregos.$B$BIl puise sa force dans les énergies qu’il doit garder – il boit dans le puits du grand aspect Malygos.$B$BMais notre victoire sur le seigneur-mage nous a permis de libérer la pleine puissance de nos drakes. Servez-vous-en avec sagesse, et Eregos succombera.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13128 AND `locale`='frFR');
