UPDATE `quest_template_locale` SET `QuestDescription`='Quand j''étais – hum – employé par le roi-liche, nous utilisions souvent un objet connu sous le nom de bâtonnet souverain pour maîtriser certains des membres les plus intelligents du Fléau.$B$BJe demande que vous m''aidiez à en construire un nouveau.$B$BHeureusement pour vous, nous avons tous les composants nécessaires sous la main : un bâtonnet de sectateur, un crochet d''abomination, une corde de Geist, et une poignée d''essences du Fléau.$B$BÇa ne devrait pas être difficile, $c.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12891 AND `locale`='frFR');
