UPDATE `quest_template_locale` SET `QuestDescription`='Oh – merci ! Je pensais vraiment que j''allais être un en-cas pour araignée. Enfin, je parle peut-être trop vite – tirons-nous d''ici !$B$BPrévenez-moi dès que vous voudrez partir... Et faites vite.', `VerifiedBuild`=25549 WHERE (`ID`=12832 AND `locale`='frFR');
