UPDATE `quest_template_locale` SET `QuestDescription`='Salut ! Mon nom est Tore. Je dirige les opérations minières ici à K3... Ou en tout cas, ça se fera bientôt !$B$BCette caverne est pleine de petites bestioles. Je pense qu''on se porterait mieux avec un peu moins d''araignées avant d''emménager – qu''en pensez-vous ?', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12829 AND `locale`='frFR');
