UPDATE `quest_template_locale` SET `LogDescription`='Détruisez 30 Charognards du désert et récupérez la faux d''Antiok. Retournez auprès d''Alexstrasza la Lieuse-de-Vie au Temple du Repos du ver si vous parvenez à accomplir cette tâche.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12498 AND `locale`='frFR');
