UPDATE `quest_template_locale` SET `QuestDescription`='Il y a des pièces détachées éparpillées un peu partout, dans les bassins Brûlants, les champs de Geysers, … Hé, et il en reste même sans doute dans la station de pompage. Rapportez-m’en tout un tas. Alors je pourrai peut-être faire fonctionner la téléportation vers l’extérieur, et bien sûr refaire l’alignement des ports d’arrivée transmatière.$B$BIl faut absolument éviter un nouvel accident…', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=11710 AND `locale`='frFR');
