UPDATE `quest_template_locale` SET `QuestDescription`='Alors voilà. Pas queschtion qu’annonce ça au ‘‘pitaine. Ch’suis une alchimiste amateur, ch’est pas mon job, et d’toute façon, j’suis en pause, là.$B$BEt pis, il est un peu grognon… et pis, vous le connaissez mieux qu’moi. Allez au donjon et dites-lui. J’suis chûre qu’il sera raisonnable… hips.$B$B<Peppy se remet à boire.>', `VerifiedBuild`=25549 WHERE (`ID`=11331 AND `locale`='frFR');
