UPDATE `quest_template_locale` SET `LogDescription`='Le Dompteur des vents Kagan, au Camp Sabot-d’Hiver, veut que vous tuiez 8 élémentaires des montagnes. Il peut s’agir de Cyclones hurlants ou d’Élémentaires Glacéclat.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=11311 AND `locale`='frFR');
UPDATE `quest_template_locale` SET `QuestDescription`='Eh bien, vous êtes là ! Notre ami va être un peu… instable. Je vous conseille de ne pas le monter tant que vous ne serez pas à Halegrince.$B$BLà-bas, utilisez l’abomination pour attirer autant de Vrykuls que possible avant qu’elle ne s’autodétruise.$B$BAh, et n’oubliez pas de ramasser les restes lorsque ce sera fini ! J’ai toujours besoin de pièces détachées !', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=11310 AND `locale`='frFR');
